const ozLiterature18Zor = <(String, String, List<String>, String)>[
  ('"İlahi Komedya"nın toplam kanto (bölüm) sayısı ve bölümlere göre dağılımı hangi seçenekte doğru verilmiştir?', '1 giriş kantosu ve her bölümde 33 kanto ile toplam 100 kanto', ['Her bir ana bölümde tam 30\'ar kanto olmak üzere toplam 90 kanto', '3 giriş kantosu ve her bölümde 33 kanto ile toplam 102 kanto', 'Cehennem\'de 40, Araf\'ta 30 ve Cennet\'te 30 kanto ile 100 kanto'], 'Cehennem bölümü genel giriş niteliğindeki 1 ekstra kantoyla 34, Araf ve Cennet ise 33\'er kantodan oluşarak Kutsal Üçleme\'ye göndermeyle 100 sayısını tamamlar.'),
  ('Dante\'nin Cehennem (Inferno) tasvirinde günahkarlara verilen cezaların işledikleri günahın doğasına ayna tutması veya tam karşıtı olması ilkesine ne ad verilir?', 'Contrapasso', ['Catharsis ilkesi', 'Memento mori', 'Amor fati anlayışı'], 'Contrapasso ilkesi uyarınca falcıların başlarının arkaya dönük olması gibi her günah kendi niteliğine uygun simgesel bir cezayla karşılık bulur.'),
  ('Dante\'nin Cehennem\'in dokuzuncu ve en dip halkasında buz gölü Cocytus içinde üç ağzıyla aynı anda çiğnenirken betimlediği üç büyük hain kimlerdir?', 'Yahuda İskariot, Brutus ve Cassius', ['Neron, Caligula ve Pontius Pilatus', 'Kabil, Kral Herod ve İskender', 'kral Minos, Odysseus ve Diomedes'], 'Şeytan\'ın üç ağzında Hz. İsa\'ya ihanet eden Yahuda ile Roma İmparatorluğu\'nun kurucu figürü Sezar\'a ihanet eden Brutus ve Cassius cezalandırılır.'),
  ('Dante Alighieri\'nin halk dilinin edebi değerini ve soyluluğunu savunmak amacıyla Latince olarak kaleme aldığı ancak tamamlayamadığı dilbilimsel inceleme eseri hangisidir?', 'De Vulgari Eloquentia', ['De Monarchia incelemesi', 'Convivio (Şölen) eseri', 'Epistolae mektupları'], 'De Vulgari Eloquentia (Halk Dilinin Belagati Üzerine), halk dilinin kurallı edebi kullanımda Latince kadar yüce olabileceğini tartışan öncü bir eserdir.'),
  ('Dante\'nin siyasi felsefesini ortaya koyduğu "De Monarchia" adlı eserinde savunduğu temel yönetim tezi aşağıdakilerden hangisidir?', 'Dünyevi barış için evrensel imparatorluk ile papalığın yetkilerinin ayrılması gerektiği', ['Tüm dünyevi krallıkların kayıtsız şartsız Roma Papası\'nın emrine girmesi gerektiği', 'İtalyan şehir devletlerinin imparatorluktan tamamen koparak bağımsız cumhuriyetler kurması', 'Kralların yalnızca Floransalı banker loncaları tarafından seçimle işbaşına getirilmesi'], 'Beyaz Guelfolar safında yer alan Dante, dünyevi mutluluk için imparatorun, ruhani kurtuluş için papanın birbirinden bağımsız yetkilere sahip olmasını savunmuştur.'),
  ('Francesco Petrarca\'nın Aziz Augustinus ile kurgusal bir iç hesaplaşma ve ruhsal sorgulama diyaloğu gerçekleştirdiği Latince düzyazı eseri hangisidir?', 'Secretum (Gizli Kitap)', ['Africa destanı', 'De Viris Illustribus', 'Trionfi (Utkular)'], 'Secretum meum adlı eserde Petrarca, Hakikat figürünün huzurunda Aziz Augustinus ile dünyevi ün tutkusu ve Laura\'ya duyduğu aşk üzerine hesaplaşır.'),
  ('Petrarca\'nın 1341 yılında Roma\'daki Capitolium Tepesi\'nde şairlik tacı (poeta laureatus) ile ödüllendirilmesini sağlayan ve İkinci Pön Savaşı\'nı konu alan Latince destanı hangisidir?', 'Africa', ['Bucolicum Carmen', 'Rerum Memorandarum', 'Itinerarium Syriacum'], 'Petrarca kendisini asıl ölümsüz kılacağına inandığı Scipio Africanus konulu Latince "Africa" destanıyla şairlik tacını almış, ancak kalıcı ününü İtalyanca şiirleriyle kazanmıştır.'),
  ('Paul Heyse\'nin "Şahin Kuramı"na (Falkentheorie) adını veren ve Decameron\'un beşinci gün dokuzuncu öyküsünde yer alan anlatıda Federigo degli Alberighi sevdiği kadını ağırlamak için hangi fedakarlığı yapar?', 'Hayattaki tek varlığı olan değerli av şahinini kesip ikram eder', ['Atalarından kalan son şatosunu Floransalı tefecilere satar', 'Kralın ordusuna paralı asker olarak yazılıp cepheye gider', 'Yıllarca biriktirdiği tüm elyazması kitaplarını manastıra bağışlar'], 'Yoksul düşen soylu Federigo, hasta oğlu için şahini istemeye gelen Monna Giovanna\'ya ikram edecek başka yiyeceği olmadığından bilmeden o şahini pişirir.'),
  ('Boccaccio\'nun Napoli yıllarındaki aşkı Maria d\'Aquino\'dan (Fiammetta) esinlenerek yazdığı ve Batı edebiyatının ilk psikolojik roman denemelerinden sayılan kadın ağzından yazılmış eseri hangisidir?', 'Elegia di Madonna Fiammetta', ['Il Filostrato destanı', 'Teseida delle nozze d\'Emilia', 'Ninfale fiesolano şiiri'], 'Terk edilmiş bir kadının iç dünyasını ve kıskançlık acılarını doğrudan kadın kahramanın ağzından anlatan Elegia di Madonna Fiammetta, psikolojik gerçekçiliğin öncüsüdür.'),
  ('"Çılgın Orlando" destanında sevgilisi Angelica\'nın sıradan bir Mağripli asker olan Medoro ile evlendiğini öğrenince aklını yitiren Orlando\'nun kayıp aklını bulmak için hipogrif adlı kanatlı atla Ay\'a çıkan şövalye kimdir?', 'Astolfo', ['Ruggiero', 'Rinaldo', 'Bradamante'], 'İngiliz şövalyesi Astolfo, dünyada yitirilen her şeyin toplandığı Ay yüzeyine çıkarak Orlando\'nun bir şişe içinde saklanan aklını yeryüzüne geri getirir.'),
  ('Ludovico Ariosto\'nun "Çılgın Orlando" eserinde şövalyelik dünyasını anlatırken benimsediği anlatıcı tutumu aşağıdakilerden hangisiyle en doğru tanımlanır?', 'İnce bir ironi, oyuncul hayal gücü ve fantastik olaylara mesafeli bir gülümseme', ['Katı bir dinsel bağnazlık ve Haçlı savaşlarını yücelten trajik ciddiyet', 'Gerçekçi köy yaşamını belgeleyen doğalcı ve karamsar bir gözlemcilik', 'Antik Yunan tragedya korolarını taklit eden kaderci ve kasvetli bir üslup'], 'Ariosto, büyülü yüzükler ve uçan atlarla dolu şövalye dünyasını Rönesans insanının olgun ironisiyle anlatarak Cervantes\'e de ilham kaynağı olmuştur.'),
  ('Tasso\'nun "Kurtarılmış Kudüs" destanında Hristiyan şövalye Tancredi\'nin gece karanlığında kimliğini bilmeden dövüşüp ölümcül şekilde yaraladığı ve ölmeden hemen önce vaftiz ettiği Müslüman kadın savaşçı kimdir?', 'Clorinda', ['Armida', 'Erminia', 'Sofronia'], 'Sevdiği kadın savaşçı Clorinda\'yı zırhı içinde tanımadan öldüren Tancredi\'nin yaşadığı trajik yıkım, destanın en dokunaklı bölümlerinden biridir.'),
  ('"Kurtarılmış Kudüs"te Hristiyan ordusunun en güçlü savaşçısı Rinaldo\'yu büyülü adasındaki bahçelerde tutsak ederek savaştan uzaklaştıran, ancak sonunda ona gerçekten aşık olan büyücü kimdir?', 'Armida', ['Alcina', 'Morgana', 'Melissa'], 'Şam kralının yeğeni büyücü Armida, Rinaldo\'yu büyüsüyle etkisiz hale getirmek isterken ona tutulur; Rinaldo kalkanında kendi yansımasını görünce büyüyü bozar.'),
  ('Pirandello\'nun "Biri, Hiçbiri, Binlercesi" (Uno, nessuno e centomila) romanında Vitangelo Moscarda\'nın karısının "burnunun biraz sağa eğri olduğu" uyarısıyla başlayan krizi hangi felsefi görüşü somutlaştırır?', 'İnsanın tek bir sabit "ben"i olmadığı, başkalarının bakışlarında yüzlerce farklı maskeye bölündüğü', ['Kalıtımsal fiziksel kusurların bireyin suç işleme eğilimini bilimsel olarak belirlediği', 'Modern tıp ve estetik cerrahinin insan ruhundaki tüm melankoliyi iyileştirebileceği', 'Geleneksel Sicilya aile yapısının bireyi tüm kimlik bunalımlarından koruduğu'], 'Moscarda kendisinin bildiği "biri"nin aslında çevresindekiler için "binlerce" farklı imge olduğunu, dolayısıyla özünde "hiçbiri" konumuna düştüğünü fark eder.'),
  ('Pirandello\'nun bir karnaval alayında attan düşüp başını çarptıktan sonra kendisini 11. yüzyıl Alman İmparatoru sanmaya başlayan ve iyileştiği halde delilik maskesini bilinçli olarak sürdüren kahramanı konu alan oyunu hangisidir?', 'IV. Kral', ['Size Öyle Geliyorsa Öyledir', 'Bu Akşam Doğaçlama Yapıyoruz', 'Giydirmek Çıplakları'], 'IV. Enrico (IV. Kral), deliliğin acımasız ve ikiyüzlü gerçek dünyaya karşı bilinçli bir sığınak olarak seçilmesini anlatan trajik bir başyapıttır.'),
  ('Italo Calvino\'nun "Görünmez Kentler" (Le città invisibili) adlı eserinde çerçeve anlatıyı oluşturan felsefi ve şiirsel diyaloglar hangi iki tarihsel figür arasında geçmektedir?', 'Venedikli gezgin Marco Polo ile Tatar İmparatoru Kubilay Han', ['Floransalı şair Dante Alighieri ile Romalı ozan Vergilius', 'Cenovalı denizci Kristof Kolomb ile İspanya Kraliçesi İsabella', 'Bilgin Galileo Galilei ile Floransa Hükümdarı Cosimo de\' Medici'], 'Marco Polo uçsuz bucaksız imparatorluğun kentlerini Kubilay Han\'a anlatırken aslında her kentte kendi memleketi Venedik\'in ve insan belleğinin farklı bir yüzünü betimler.'),
  ('Calvino\'nun "Ağaca Tüneyen Baron" romanında on iki yaşındayken babasının zorla yedirmek istediği salyangoz yemeğini reddederek bahçedeki meşe ağacına çıkan ve ömrünün sonuna dek bir daha hiç yere inmeyen kahraman kimdir?', 'Cosimo Piovasco di Rondò', ['Medardo di Terralba', 'Agilulfo Emo Bertrandino', 'Amerigo Ormea'], 'Baron Cosimo ağaçların tepesinde kalarak Aydınlanma Çağı düşünürleriyle mektuplaşır, topluma yukarıdan ama duyarlı bir mesafeden katılmanın simgesi olur.'),
  ('Italo Calvino\'nun matematik ile edebiyatı birleştiren Fransız "Oulipo" grubunun etkisiyle yazdığı, konuşma yetisini yitirmiş yolcuların hayat hikayelerini yalnızca iskambil-tarot kartlarını dizerek anlattığı eseri hangisidir?', 'Kesişen Yazgılar Şatosu', ['Örümceklerin Yuvalandığı Patika', 'Arjantin Karıncası', 'Emlak Vurgunu'], 'Kesişen Yazgılar Şatosu (Il castello dei destini incrociati), sınırlı sayıdaki tarot kartının farklı dizilimlerinden sonsuz öykü üretme kombinasyonuna dayanır.'),
  ('"Gülün Adı"nda kör kütüphaneci Burgoslu Jorge\'nin komedya kitabını ölüm pahasına gizlemesinin altında yatan temel teolojik korku nedir?', 'Gülmenin korkuyu yok edeceği, Şeytan korkusu kalmazsa inanç ve otoritenin sarsılacağı', ['Kitaptaki simya formüllerinin manastır hazinesindeki altınları değersizleştireceği', 'Yunanca metinlerin Latincenin kilise içindeki dil üstünlüğünü zayıflatacağı', 'Aristoteles\'in felsefesinin manastırdaki şifalı bitki tarımını yasaklaması'], 'Arjantinli kör yazar Jorge Luis Borges\'e bir saygı duruşu olan Burgoslu Jorge, gülmenin kutsal otoriteye duyulan korkuyu yıkacağından çekinir.'),
  ('Umberto Eco\'nun bir yayınevinde çalışan üç editörün şakayla uydurduğu gizli Tapınak Şövalyeleri planının kontrolden çıkarak gerçek fanatikleri harekete geçirmesini anlattığı komplo teorisi eleştirisi romanı hangisidir?', 'Foucault Sarkacı', ['Önceki Günün Adası', 'Baudolino', 'Prag Mezarlığı'], 'Foucault Sarkacı (Il pendolo di Foucault), her şeyi birbiriyle ilişkilendiren hermetik ve paranoyak yorumlama alışkanlığının tehlikelerini sergiler.'),
  ('Umberto Eco\'nun "Açık Yapıt" (Opera aperta) adlı kuramsal çalışmasında ortaya koyduğu temel edebiyat ve sanat düşüncesi aşağıdakilerden hangisidir?', 'Sanat eserinin anlamının tek ve kapalı olmayıp okurun/alıcının etkin yorumuyla çoğaldığı', ['Yalnızca tamamlanmamış ve yarım bırakılmış taslak metinlerin sanatsal değer taşıdığı', 'Edebi metinlerin telif hakları olmaksızın herkes tarafından yeniden yazılması gerektiği', 'Yazarın niyetinin dışında yapılan her türlü okur yorumunun geçersiz sayılması gerektiği'], 'Eco\'ya göre özellikle modern sanat yapıtları, okura çoklu anlamlandırma ve yorumlama koridorları sunan "açık" bir gösterge dizgesidir.'),
  ('Cervantes\'in "Don Kişot"un 1605\'teki birinci cildinde öyküyü kurgusal olarak hangi Arap tarihçinin yazdığı bir elyazmasının çevirisiymiş gibi sunarak üstkurmaca oyunu yapmıştır?', 'Seyyid Hamid Badincani', ['İbn Rüşd el-Kurtubi', 'Ebu Bekir İbn Tufeyl', 'El-İdrisi el-Endülüsi'], 'Cervantes Toledo pazarında bulunan Arapça defterlerin yazarı olarak uydurduğu Cide Hamete Benengeli figürüyle anlatıcı güvenilirliğini ustaca sorgulamıştır.'),
  ('1614 yılında "Avellaneda" takma adlı meçhul bir yazarın sahte bir "İkinci Cilt" yayımlaması üzerine Cervantes\'in 1615\'te yayımladığı gerçek ikinci ciltte başvurduğu yenilikçi kurgusal hamle nedir?', 'Kahramanların birinci cildi okumuş insanlarla karşılaşması ve sahte kitabı bizzat yalanlaması', ['Don Kişot karakterini tamamen çıkarıp yalnızca Sancho Panza\'nın gençliğini anlatması', 'Romanı düzyazıdan çıkararak baştan sona üç perdelik koşuklu bir tragedya şeklinde yazması', 'Sahte yazarı mahkemeye verdiği dilekçe metinlerini romanın son on bölümü olarak basması'], 'İkinci ciltte Don Kişot ve Sancho hem kendileri hakkında yazılmış gerçek birinci cildin şöhretiyle yüzleşir hem de sahte Avellaneda kitabının yanlışlarını çürütürler.'),
  ('Miguel de Cervantes\'in 1571 yılında Osmanlı donanmasıyla yapılan hangi deniz savaşında sol elini kullanamaz hale getiren ağır yarayı alması nedeniyle kendisine "İnebahtı Çolağı" (El manco de Lepanto) lakabı verilmiştir?', 'İnebahtı (Lepanto) Deniz Savaşı', ['Preveze Deniz Savaşı', 'Cerbe Deniz Savaşı', 'Tunus Kuşatması'], 'Kutsal İttifak donanmasında çarpışan Cervantes göğsünden ve sol elinden yaralanmış, sol elini kaybetmese de ömür boyu işlevsiz kalmıştır.'),
  ('Cervantes\'in İspanyol edebiyatına İtalyan tarzı kısa öykü türünü kazandırdığı ve içinde "Cam Lisanslı", "Çingene Kızı", "Köpeklerin Söyleşisi" gibi ünlü anlatıların yer aldığı 12 öykülük eseri hangisidir?', 'Örnek Alınacak Öyküler (Novelas ejemplares)', ['Galatea (Pastoral Roman)', 'Persiles ve Sigismunda\'nın İşleri', 'Parnas\'a Yolculuk (Viaje del Parnaso)'], '1613\'te yayımlanan Novelas ejemplares, Cervantes\'in İspanyol dilinde çeviriye dayanmayan ilk özgün kısa öyküleri yazma iddiasını taşıyan başyapıtıdır.'),
  ('Lope de Vega\'nın atasözüne dönüşen bir halk deyiminden yola çıkarak yazdığı, sekreteri Teodoro\'yu ne kendisiyle evlenmeye layık gören ne de başkasına yar eden kıskanç Kontes Diana\'yı anlattığı komedyası hangisidir?', 'Bahçıvanın Köpeği (El perro del hortelano)', ['Aptal Kız (La dama boba)', 'Cezasız İntikam (El castigo sin venganza)', 'Çelik Madrid Suları (El acero de Madrid)'], '"Ne kendi yer ne başkasına yedirir" anlamındaki İspanyol deyiminden adını alan Bahçıvanın Köpeği, sınıf farkı ile aşk tutkusu arasındaki çatışmayı nükteli biçimde işler.'),
  ('Calderón de la Barca\'nın onurlu ve varlıklı köylü Pedro Crespo\'nun, kızını kaçırıp kirleten soylu yüzbaşı Don Álvaro\'yu belediye başkanı seçildikten sonra yargılayıp idam ettirmesini konu alan onur dramı hangisidir?', 'Zalamea Kadısı', ['Kendi Onurunun Hekimi', 'Gizli Hakarete Gizli İntikam', 'Büyük Dünya Tiyatrosu'], 'Zalamea Kadısı\'nda Pedro Crespo "malımız ve canımız kralındır, ama onur ruhun malıdır ve ruh yalnızca Tanrı\'nındır" sözüyle onurun sınıfsal ayrıcalık olmadığını haykırır.'),
  ('Calderón de la Barca\'nın yetkinleştirdiği, Katolik Yortusu (Corpus Christi) şenliklerinde açık havada tek perdelik alegorik oyunlar olarak sahnelenen İspanyol dinsel tiyatro türüne ne ad verilir?', 'Auto sacramental', ['Entremés', 'Zarzuela', 'Sainete'], 'İman, Günah, Ölüm, Dünya gibi soyut kavramların kişileştirildiği "auto sacramental" türünün en ünlü örneği Calderón\'un "Büyük Dünya Tiyatrosu" adlı eseridir.'),
  ('"Kanlı Düğün"ün üçüncü perdesindeki gece ormanı sahnesinde kaçan aşıkların yerini aydınlatarak yakalanmalarına yol açan "Ay" ve yaşlı bir dilenci kadın kılığındaki "Ölüm" figürlerinin kullanımı neyi gösterir?', 'Lorca\'nın gerçekçi köylü dramını sürrealist ve mitolojik şiirsel simgelerle birleştirdiğini', ['Oyunun tamamının çocuk izleyicilere yönelik neşeli bir peri masalı olarak yazıldığını', 'Endülüs köylülerinin modern astronomi ve tıp bilimine duyduğu derin güveni', 'Yazarın İspanyol tiyatrosundan tüm şiirsel ve lirik öğeleri temizlemek istediğini'], 'Lorca gazetede okuduğu gerçek bir köy cinayetini Ay, Ölüm ve Ormancıların şiirsel-alegorik sahnesiyle kozmik bir kader tragedyasına dönüştürmüştür.'),
  ('"Bernarda Alba\'nın Evi"nin sonunda yeşil elbisesiyle yasa başkaldıran ve Bernarda\'nın bastonunu kıran en küçük kız Adela\'yı kendini asarak intihara sürükleyen olay nedir?', 'Bernarda\'nın tüfekle ateş edip Pepe\'yi öldürdüğünü söyleyerek kızını aldatması', ['Ablası Martirio\'nun Adela\'nın tüm çeyiz sandığını köy meydanında ateşe vermesi', 'Büyükannesi María Josefa\'nın evin kapılarını kilitleyip anahtarları kuyuya atması', 'Hizmetçi Poncia\'nın gizli aşkı kasaba rahibine ve jandarmaya ihbar etmesi'], 'Pepe el Romano tüfek atışından kurtulup atıyla kaçtığı halde Martirio ve Bernarda onun öldüğünü ima edince, umudunu yitiren Adela odasına kapanıp canına kıyar.'),
  ('Federico García Lorca\'nın "Yerma" adlı tragedyasında "çorak, verimsiz" anlamına gelen adıyla özdeşleşen kadın kahramanı en sonunda kendi kocasını boğarak öldürmeye iten temel trajik saplantı nedir?', 'Anne olma arzusuyla yanıp tutuşurken kocasının duygusuzluğu ve çocuksuzluğa mahkum oluşu', ['Kocasının aile mirası olan zeytinlikleri kumarda yabancı tüccarlara kaybetmesi', 'Kasabadaki iç savaş sırasında kocasının karşı cepheye casusluk yaptığını öğrenmesi', 'Kocasının başka bir köyden gizlice ikinci bir evlilik yaptığının ortaya çıkması'], 'Namus anlayışı nedeniyle başka bir erkekten çocuk sahibi olmayı reddeden Yerma, kocasının çocuk istemediğini kesin olarak söylemesi üzerine kendi soy umudunu kocasını öldürerek noktalar.'),
  ('"İlahi Komedya"nın Cennet (Paradiso) bölümünün son kantosunda Vergilius\'un çoktan ayrıldığı ve Beatrice\'nin de yerini aldığı son aşamada Dante\'nin Meryem Ana\'ya aracılık etmesi için dua eden aziz kimdir?', 'Clairvauxlu Aziz Bernard', ['Assisili Aziz Francesco', 'Aquinolu Aziz Thomas', 'Padovalı Aziz Antonio'], 'Mistik teolojinin temsilcisi Aziz Bernard, otuz üçüncü kantoda Meryem Ana\'ya ünlü duasını sunarak Dante\'nin Tanrısal Işık ile bütünleşmesine aracılık eder.'),
  ('Dante\'nin Cehennem\'in yirmi altıncı kantosunda alevden bir dil içinde yanarken konuşturduğu, yaşlılığında bile bilgi tutkusuyla Herkül Sütunları\'nı (Cebelitarık) aşıp bilinmeyen okyanusa açılan mitolojik kahraman kimdir?', 'Odysseus (Ulysses)', ['Aeneas (Enea)', 'Akhilleus (Achille)', 'İason (Giasone)'], 'Dante, Homeros geleneğinden farklı bir son kurgulayarak Odysseus\'u "insan hayvan gibi yaşamak için değil, erdem ve bilgi izlemek için yaratıldı" diyerek okyanusa açılan trajik bir kaşif olarak çizer.'),
  ('Cehennem\'in otuz üçüncü kantosunda Pisa Başpiskoposu Ruggieri tarafından çocukları ve torunlarıyla birlikte Açlık Kulesi\'ne hapsedilerek ölüme terk edilen ve buz gölünde düşmanının kafatasını kemiren soylu kimdir?', 'Kont Ugolino della Gherardesca', ['Farinata degli Uberti', 'Pier della Vigna', 'Brunetto Latini'], 'Kont Ugolino\'nun kulede açlıktan can veren evlatlarının acısını anlattığı bölüm, İlahi Komedya\'nın en sarsıcı dramatik pasajlarından biridir.'),
  ('Petrarca\'nın "Canzoniere" (Rerum vulgarium fragmenta) adlı şiir toplamı yapısal olarak hangi iki ana bölüme ayrılmaktadır?', 'Laura\'nın sağlığında yazılan şiirler ve Laura\'nın ölümünden sonra yazılan şiirler', ['Avignon\'da yazılan gençlik şiirleri ve Venedik\'te yazılan yaşlılık şiirleri', 'Aşk konulu dünyevi soneler ve Haçlı seferlerini öven epik kasideler', 'Latince kaleme alınan ilahiler ve Toskana lehçesiyle yazılan halk türküleri'], 'Toplam 366 şiirden oluşan Canzoniere, Laura\'nın 1348 veba salgınında ölümüyle "In vita di Madonna Laura" ve "In morte di Madonna Laura" olarak ikiye ayrılır.'),
  ('Petrarca\'nın alegorik bir görü (vizyon) çerçevesinde Aşk\'ın İffet\'e, İffet\'in Ölüm\'e, Ölüm\'ün Ün\'e, Ün\'ün Zaman\'a ve Zaman\'ın Sonsuzluk\'a yenilişini Dante\'nin terza rima nazmıyla anlattığı eseri hangisidir?', 'Trionfi (Utkular / Zaferler)', ['De Vita Solitaria (Yalnız Yaşam)', 'De Remediis Utriusque Fortunae', 'Rerum Memorandarum Libri'], 'Trionfi (Zafer Alayları), insani tutkuların geçiciliğini ve yalnızca Tanrısal Sonsuzluk\'un kalıcı zaferini işleyen altı bölümlük alegorik bir şiirdir.'),
  ('"Decameron"un dördüncü gün beşinci öyküsünde ağabeyleri tarafından öldürülen sevgilisi Lorenzo\'nun kesik başını bir fesleğen saksısına gömüp gözyaşlarıyla sulayan ve Keats\'in ünlü bir şiirine konu olan genç kız kimdir?', 'Lisabetta da Messina', ['Caterina da Valbona', 'Madonna Filippa', 'Ginevra degli Almieri'], 'John Keats\'in "Isabella ya da Fesleğen Saksısı" şiirine ilham veren Lisabetta öyküsü, Decameron\'un trajik aşk temalı dördüncü gününün en unutulmaz anlatısıdır.'),
  ('Giovanni Boccaccio\'nun ömrünün son yıllarında hümanist dostu Petrarca\'nın da teşvikiyle derlediği ve antik mitoloji bilgisini yüzyıllar boyunca Avrupa\'ya aktaran Latince ansiklopedik eseri hangisidir?', 'Pagan Tanrılarının Soyağacı (Genealogia deorum gentilium)', ['Ünlü Kadınlar Üzerine (De mulieribus claris)', 'Talihsiz Ünlü Kişilerin Yazgısı (De casibus virorum)', 'Dante\'nin Yaşamı Üzerine İnceleme (Trattatello)'], 'Genealogia deorum gentilium, Yunan ve Roma mitolojisini sistematik ve alegorik olarak açıklayan Rönesans\'ın en kapsamlı mitoloji başvuru kaynağıdır.'),
  ('Ariosto\'nun "Çılgın Orlando" destanının hemen başında güzeller güzeli Doğu prensesi Angelica\'nın peşinden koşarken hem Hristiyan hem Müslüman şövalyelerin büyülü "Unutuş ve Aşk Çeşmeleri"nden içerek sürekli duygularının tersine döndüğü orman hangisidir?', 'Ardennes Ormanı', ['Sherwood Ormanı', 'Kara Orman', 'Vallombrosa Ormanı'], 'Ardennes Ormanı\'ndaki iki büyülü pınardan biri aşk ateşini tutuştururken diğeri nefrete çevirir; böylece Rinaldo ve Angelica sürekli birbirinden kaçar veya birbirini kovalar.'),
  ('Torquato Tasso\'nun ruhsal bunalımlar ve Engizisyon kuşkuları yüzünden kendi başyapıtı "Kurtarılmış Kudüs"ü yıllar sonra aşk ve büyü sahnelerini budayarak çok daha katı dinsel kurallarla yeniden yazdığı versiyonun adı nedir?', 'Fethedilmiş Kudüs (Gerusalemme Conquistata)', ['Kutsal Kudüs (Gerusalemme Sacra)', 'Yaratılışın Yedi Günü (Il Mondo Creato)', 'Rinaldo ve Şövalyeleri (Il Rinaldo)'], '1593\'te yayımlanan Gerusalemme Conquistata şairin aşırı özsansürünün ürünü olmuş, ancak edebiyat tarihi her zaman ilk ve canlı yapıt olan Gerusalemme Liberata\'yı başyapıt kabul etmiştir.'),
  ('Pirandello\'nun "tiyatro içinde tiyatro" (metatiyatro) üçlemesini oluşturan üç oyun aşağıdaki seçeneklerin hangisinde bir arada doğru verilmiştir?', 'Altı Karakter Yazarını Arıyor, Herkes Kendi Rolünde, Bu Akşam Doğaçlama Yapıyoruz', ['IV. Kral, Size Öyle Geliyorsa Öyledir, Giydirmek Çıplakları', 'Liolà, Sicilya Turunçları, Ağzı Çiçekli Adam', 'Dağ Devleri, Yeni Koloni, Lazarus Efsanesi'], 'Pirandello bu üçlemede sırasıyla yazar-karakter-oyuncu çatışmasını, seyirci-sahne ilişkisini ve yönetmen otoritesiyle doğaçlama gerilimini irdeler.'),
  ('Pirandello\'nun ölmeden önce üzerinde çalıştığı, modern toplumda şiirin ve sanatın hayatta kalıp kalamayacağını sorgulayan ancak son perdesini tamamlayamadığı "mitos" oyunu hangisidir?', 'Dağ Devleri (I giganti della montagna)', ['Ağzı Çiçekli Adam (L\'uomo dal fiore in bocca)', 'Kavanoz (La giara)', 'Düşün İyi Düşün Giacomino'], 'Dağ Devleri\'nde gezgin tiyatrocu Kontes Ilse, maddi güç peşindeki duyarsız kitleler arasında sanatı yaşatmaya çalışırken trajik biçimde kurban olur.'),
  ('Italo Calvino\'nun Büyük Patlama\'dan galaksilerin oluşumuna ve dinozorların yok oluşuna kadar bilimsel evrim kuramlarını yaşlı ve ölümsüz bir varlık olan "Qfwfq"nun ağzından mizahi öykülere dönüştürdüğü eseri hangisidir?', 'Kozmokomik Öyküler', ['Palomar', 'Görünmez Kentler', 'Amerika Dersleri'], 'Kozmokomik Öyküler\'de adını tersten okursak da aynı kalan Qfwfq, evrenin tek bir noktaya sıkıştığı zamanları eski mahalle anıları gibi sıcak bir dille anlatır.'),
  ('Italo Calvino\'nun 1985 yılında Harvard Üniversitesi\'nde vermek üzere hazırladığı, ancak konuşmaları yapamadan vefat etmesi üzerine "Hafiflik, Hız, Kesinlik, Görünürlük, Çokluk" başlıklarıyla yayımlanan edebiyat kuramı eseri hangisidir?', 'Yeni Bin Yıl İçin Altı Öneri', ['Klasikleri Niçin Okumalıyız?', 'Edebiyat Makinesi', 'Yolun Başındaki İlk Yıllar'], 'Altıncı dersi olan "Tutarlılık"ı yazamadan hayatını kaybeden Calvino, bu eserde edebiyatın gelecek yüzyıla taşıması gereken temel estetik değerleri belirlemiştir.'),
  ('Umberto Eco\'nun 17. yüzyılda geçen ve boylam çizgisinin tam üzerinde demirli terk edilmiş "Daphne" adlı gemide mahsur kalan Roberto della Griva\'nın barok düşüncelerle dolu serüvenini anlattığı romanı hangisidir?', 'Önceki Günün Adası (L\'isola del giorno prima)', ['Kraliçe Loana\'nın Gizemli Alevi', 'Sıfır Sayı (Numero Zero)', 'Baudolino'], 'Önceki Günün Adası, tarih değiştirme çizgisi üzerinde yüzme bilmeden gemide kalan kahramanın zaman, mekan, ikiz kardeşi ve sonsuzluk üzerine barok kurgularını işler.'),
  ('Umberto Eco\'nun İmparator Friedrich Barbarossa\'nın manevi oğlu olan sevimli bir yalancının 1204 Dördüncü Haçlı Seferi sırasında yağmalanan İstanbul\'da (Konstantinopolis) başlayıp Rahip Kral İoannes\'in ülkesine uzanan öyküsünü anlattığı romanı hangisidir?', 'Baudolino', ['Prag Mezarlığı', 'Foucault Sarkacı', 'Gülün Adı'], 'Baudolino, uydurduğu efsaneler zamanla tarihsel gerçekmiş gibi kabul gören bir kahraman üzerinden tarih yazımı ile kurmaca arasındaki sınırı sorgular.'),
  ('Don Kişot\'u şövalyelik deliliğinden kurtarıp köyüne geri götürmek amacıyla "Beyaz Ay Şövalyesi" kılığına girerek Barselona kumsalında onu düelloda yenen ve bir yıl silah bırakma sözü alan köylüsü kimdir?', 'Üniversiteli Sansón Carrasco', ['Berber Maestro Nicolás', 'Köy Rahibi Pero Pérez', 'Çoban Grisóstomo'], 'Daha önce "Aynalar Şövalyesi" kılığında yenilen genç bilgin Sansón Carrasco, ikinci denemesinde "Beyaz Ay Şövalyesi" olarak Don Kişot\'u alt edip evine dönmeye mecbur bırakır.'),
  ('Don Kişot\'un birinci cildinde kahramanın şövalye romanslarının büyüsüne kapılmasında en büyük esin kaynağı olarak sıkça andığı ve berberle rahibin kitap yakma sahnesinde "türünün en iyisi" diyerek ateşe atmaktan vazgeçtiği İspanyol şövalye kitabı hangisidir?', 'Galyalı Amadís (Amadís de Gaula)', ['Beyaz Tirant (Tirant lo Blanc)', 'İngiltereli Palmerín', 'Yunanlı Don Belianís'], 'Garci Rodríguez de Montalvo\'nun düzenlediği Amadís de Gaula, şövalye romanslarının başyapıtı olduğu için köy rahibi tarafından yangından bağışlanan ilk kitaptır.'),
  ('Cervantes\'in "Örnek Alınacak Öyküler" kitabında yer alan ve yediği büyülü bir ayva yüzünden bedeninin tamamen camdan yapıldığına, dokunulursa kırılacağına inanan ama keskin zekasıyla herkese bilgece yanıtlar veren öğrenciyi anlatan öykü hangisidir?', 'Cam Lisanslı (El licenciado Vidriera)', ['Kıskanç Extremaduralı (El celoso extremeño)', 'Rinconete ile Cortadillo', 'Şanlı Bulaşıkçı Kız (La ilustre fregona)'], 'Tomás Rodaja adlı hukuk öğrencisinin "Cam Lisanslı" sanrısıyla toplumsal ikiyüzlülükleri doğruyu söyleyen bir deli özgürlüğüyle eleştirmesi, Don Kişot temasıyla yakın akrabadır.'),
  ('Miguel de Cervantes\'in MÖ 133 yılında Romalı komutan Scipio Aemilianus tarafından kuşatılan İberya kentinin teslim olmaktansa son ferdine kadar ölümü seçmesini anlattığı klasik trajedisi hangisidir?', 'Numancia Kuşatması (El cerco de Numancia)', ['Cezayir\'deki Yaşam (El trato de Argel)', 'Cesur İspanyol (El gallardo español)', 'Kıskançlık Evi (La casa de los celos)'], 'Numancia Kuşatması, kolektif direnişi ve özgürlük uğruna ölüme yürüyen bir halkın trajik yüceliğini sahneleyen İspanyol Rönesans tiyatrosunun en önemli trajedilerindendir.'),
  ('Cervantes\'in ölüm döşeğindeyken önsözünü imzaladığı ve ölümünden bir yıl sonra (1617) yayımlanan, kuzeyin buzlu denizlerinden Roma\'ya uzanan serüvenleriyle kendisinin en kusursuz eseri saydığı son romanı hangisidir?', 'Persiles ve Sigismunda\'nın İşleri', ['Galatea', 'Parnas\'a Yolculuk', 'Sekiz Komedya ve Sekiz Ara Oyun'], 'Antik Yunan yazarı Heliodoros\'un "Etiyopya Öyküleri"ni örnek alan Bizans tarzı romans "Los trabajos de Persiles y Sigismunda", yazarın hayata veda ettiği son yapıtıdır.'),
  ('Lorca\'nın "Bernarda Alba\'nın Evi" oyununda evin kilitli bir odasında tutulan, akıl sağlığı yerinde olmayan ancak "deniz kıyısında evlenip özgür olmak istediğini" haykırarak kızların bastırılmış arzularını dile getiren seksen yaşındaki büyükanne kimdir?', 'María Josefa', ['La Poncia', 'Prudencia', 'Magdalena'], 'Bernarda\'nın annesi María Josefa gelinlik giyip kucağında bir kuzuyla sahneye çıkarak, taş duvarlar ardına gömülen doğurganlık ve özgürlük özleminin şiirsel sesi olur.'),
  ('"Bernarda Alba\'nın Evi"nin hem en başında hem de Adela\'nın intiharından hemen sonraki son sahnesinde Bernarda\'nın kızlarına buyurduğu ilk ve son kelime olan "Susun!" (¡Silencio!) emri yapısal olarak neyi simgeler?', 'Trajik ölüme rağmen baskıcı düzenin ve toplumsal görünüş kaygısının kırılmadan sürdüğünü', ['Ailenin sekiz yıllık yası sona erdirip köy halkıyla barışmaya karar verdiğini', 'Kızların annelerini affederek kendi istekleriyle rahibe olmayı kabul ettiklerini', 'Kasabadaki yargıcın olayı araştırmak için evde sessizlik ilan ettiğini'], 'Bernarda Alba kızının ölümünden sonra bile tek derdi "kızım bakire öldü deyin, kimse ağlamasın" demek olan acımasız bir otoritedir; oyunun "Susun!" sözüyle açılıp kapanması kapalı döngüyü pekiştirir.'),
  ('Lorca\'nın 1831 yılında Granada\'da özgürlükçülerin bayrağını işlediği için Kral VII. Fernando rejimi tarafından idam edilen tarihsel bir kadın kahramanı sahneye taşıdığı romantik-tarihsel oyunu hangisidir?', 'Mariana Pineda', ['Yerma', 'Kanlı Düğün', 'Seyirci'], '1927\'de dekorlarını Salvador Dalí\'nin tasarladığı Mariana Pineda, aşk ile politik özgürlük ülküsünü aynı bayrakta birleştiren fedakar bir kadının dramıdır.'),
  ('Lorca\'nın sağlığında sahnelenemeyecek kadar cüretkar bulduğu "imkansız tiyatro" (teatro imposible) kapsamında yazdığı, maskelerin ardındaki bastırılmış kimlikleri ve gerçeküstücü sahne devrimini işlediği oyunu hangisidir?', 'Seyirci (El público)', ['Kanlı Düğün (Bodas de sangre)', 'Eskicinin Harika Karısı', 'Bernarda Alba\'nın Evi'], 'El público (Seyirci), burjuva tiyatrosunun sahte yüzeyini yırtarak "kumun altındaki tiyatroyu" ve bireyin en mahrem kimlik çatışmalarını gerçeküstücü bir dille sahneye taşır.'),
  ('Hem Pirandello\'nun "Altı Karakter Yazarını Arıyor" oyununda hem de Cervantes\'in "Don Kişot"unun ikinci cildinde ortak olarak kullanılan ve modern/postmodern edebiyatın temelini oluşturan anlatı stratejisi hangisidir?', 'Kurgusal karakterlerin kendi edebi varlıklarının ve yazarlarının farkında olarak kurmaca sınırını aşması', ['Olayların yalnızca bilimsel deney raporları ve mahkeme tutanakları üzerinden nesnel biçimde aktarılması', 'Tüm karakterlerin kırsal lehçeyle konuşup soylu sınıfa karşı silahlı köylü ayaklanması başlatması', 'Anlatının başında ve sonunda antik mitoloji tanrılarının gökten inerek çatışmayı çözmesi'], 'Cervantes roman sanatında, Pirandello ise tiyatro sanatında kurmaca kişileri kendi yazılış süreçleriyle yüzleştirerek üstkurmaca/metatiyatro devrimini gerçekleştirmiştir.'),
  ('Umberto Eco\'nun "Gülün Adı" ile Italo Calvino\'nun "Bir Kış Gecesi Eğer Bir Yolcu" romanları postmodern İtalyan edebiyatı bağlamında değerlendirildiğinde hangi ortak özelliği paylaşırlar?', 'Metinlerarasılık, okuma eyleminin merkeze alınması ve dedektiflik/arayış kurgusunun felsefi düzleme taşınması', ['İkinci Dünya Savaşı sonrasındaki fabrika grevlerini belgesel ve yalın bir röportaj diliyle aktarmaları', 'Yalnızca tek bir odada geçen diyaloglardan oluşup tarihsel ve edebi göndermeleri tümüyle reddetmeleri', 'Geleneksel ottava rima ölçüsüyle yazılmış manzum şövalye destanları biçiminde kurgulanmaları'], 'Her iki eser de kitapları, kütüphaneleri, kayıp elyazmalarını ve okurun anlam arayışını postmodern bir metinlerarası labirente dönüştürür.'),
  ('İtalyan ve İspanyol edebiyatlarının Rönesans\'tan 20. yüzyıla uzanan büyük klasiklerinde (Boccaccio, Ariosto, Cervantes, Pirandello, Calvino, Eco) ortak bir damar olarak öne çıkan en belirgin biçimsel eğilim nedir?', 'Çerçeve anlatı, üstkurmaca ve kurgu ile gerçeklik arasındaki sınırları sorgulayan çok katmanlı oyuncul yapı', ['Doğa betimlemelerini tamamen dışlayarak yalnızca tek sesli lirik manastır ilahileri üretme geleneği', 'Klasik Latince dışındaki tüm halk dillerini edebi metinlerde kullanmaktan kaçınan seçkinci tutum', 'Bireysel psikolojiyi yok sayarak yalnızca sanayi devrimi makinelerinin teknik işleyişini anlatma çabası'], 'Decameron\'un çerçeve öyküsünden Don Kişot\'un Arapça elyazması oyununa, Pirandello\'nun metatiyatrosundan Calvino ve Eco\'nun postmodern labirentlerine dek Akdeniz klasikleri anlatma sanatının kendi doğasını sorgulamada öncü olmuştur.'),
  ('Borges\'in "İbn Rüşd\'ün Arayışı" (La busca de Averroes) öyküsünde Endülüslü filozofun Aristoteles\'in "Poetika"sındaki "tragedya" ve "komedya" kavramlarını bir türlü çözememesinin nedeni nedir?', 'İslam kültür çevresinde tiyatro temsili geleneği bulunmadığı için kendi kavramsal ufku dışındaki bir sanatı yalnızca metinden tahayyül edememesi', ['Yunanca elyazmalarının Bağdat\'taki yangında yok olması yüzünden eline yalnızca eksik Süryanice özetlerin ulaşması', 'Kurtuba halifesinin felsefi şerh çalışmalarını yasaklayarak İbn Rüşd\'ü Fas\'a sürgüne göndermesi', 'İbn Rüşd\'ün şiiri mantık bilimine bütünüyle aykırı bularak edebi kavramları kasten yanlış tercüme etmesi'], 'Borges, avlusunda oyun oynayan çocuklarda ve bir gezginin Çin tiyatrosu anlatısında cevabın burnunun dibinde olmasına rağmen, kültürel bağlam olmadan çevirinin imkansızlığını gösterir; sonunda kendi çabasının da benzer bir yenilgi olduğunu söyler.'),
  ('Borges\'in 1935\'te yayımlanan, haydutların, korsanların ve sahte peygamberlerin kurgulanmış biyografilerini bir araya getirdiği ve büyülü gerçekçiliğin öncülerinden sayılan düzyazı kitabı hangisidir?', 'Alçaklığın Evrensel Tarihi', ['Sonsuzluğun Tarihi', 'Yaratıcı', 'Brodie Raporu'], '"Alçaklığın Evrensel Tarihi" (Historia universal de la infamia), Billy the Kid\'den Mervli Peçeli Peygamber Hakîm\'e uzanan yarı belgesel, yarı kurmaca öykülerden oluşur.'),
  ('Borges\'in "Güney" (El Sur) öyküsünde kütüphaneci Juan Dahlmann\'ın bir taşra hanında bıçaklı kavgaya çıkışı neden çift katmanlı bir okumaya açıktır?', 'Hem Arjantin bozkırında romantik bir ölüm seçimi hem de sanatoryumda septisemiden ölen Dahlmann\'ın son andaki sanrısı olarak okunabilmesi', ['Dahlmann\'ın kavga ettiği yaşlı gaucho\'nun aslında yıllar önce cephede ölen kendi öz babası çıkması', 'Öykünün ilk yarısının İspanyolca, ikinci yarısının ise Alman göçmenlerin lehçesiyle yazılmış olması', 'Anlatıcının metnin sonunda Dahlmann\'ın aslında hiç var olmadığını ve bir gazete ilanından uydurulduğunu açıklaması'], 'Borges, kendisinin de "belki de en iyi öyküm" dediği "Güney"de, başını pencere kanadına çarpıp kan zehirlenmesi yaşayan Dahlmann\'ın güneye yolculuğunu sanatoryumdaki ölüm döşeği düşü olarak da okunacak biçimde kurgular.'),
  ('"Yüzyıllık Yalnızlık" romanında yaklaşık üç bin muz işçisinin meydanda makineli tüfeklerle katledildiği, ancak resmi tarih ve kasaba halkı tarafından hiç olmamış sayılan olaydan sağ kurtulan Buendía kimdir?', 'José Arcadio Segundo', ['Aureliano Segundo', 'Albay Aureliano Buendía', 'Mauricio Babilonia'], '1928 Ciénaga Muz Katliamı\'ndan esinlenen sahnede José Arcadio Segundo ölülerle dolu iki yüz vagonluk trenden atlayıp kurtulur; fakat kimse katliamın yaşandığına inanmaz ve o da Melquíades\'in odasına kapanır.'),
  ('"Yüzyıllık Yalnızlık" romanının finalinde Aureliano Babilonia\'nın Melquíades\'in parşömenlerini çözmesiyle kasabanın kasırgayla silinmesi, eserin zaman anlayışı açısından neyi kanıtlar?', 'Tarihin çizgisel ilerlemek yerine kendi kuyruğunu ısıran döngüsel bir yazgı olduğunu ve okuma eylemiyle yaşama anının son satırda çakıştığını', ['Buendía ailesinin günahlarından arınarak uygar bir sanayi kenti kurmak üzere Macondo\'yu kendi elleriyle yıktığını', 'Melquíades\'in kehanetlerinin yanlış çıktığını ve domuz kuyruklu bebeğin aileyi sonsuza dek yaşatacağını', 'Büyülü gerçekçilik unsurlarının romanın sonunda yerini tamamen belgesel bir tarih yazımına bıraktığını'], 'Aureliano Babilonia domuz kuyruklu oğlunun karıncalarca yendiğini görüp "Ailenin ilki bir ağaca bağlanmış, sonuncusunu da karıncalar yiyor" epigrafını çözdüğünde, okuduğu an ile yaşadığı an birleşir ve yüz yıllık yalnızlığa mahkum soylara ikinci bir şans verilmez.'),
  ('Pablo Neruda\'nın 1930\'ların başında Uzak Doğu\'da konsolosluk yaparken yaşadığı derin yabancılaşmayı ve doğadaki dağılma-çürüme imgelerini gerçeküstücü bir yoğunlukla işlediği şiir dizisi hangisidir?', 'Yeryüzünde Konaklama', ['Kaptanın Dizeleri', 'Alacakaranlık Kitabı', 'Evrensel Şarkı'], '"Yeryüzünde Konaklama" (Residencia en la tierra), Rangoon, Kolombo ve Cava\'daki yalnızlık yıllarından beslenen, varoluşsal bunalım ve yoğun metaforlarla örülü başyapıtıdır.'),
  ('Pablo Neruda\'nın 1973\'teki ölümünden hemen sonra yayımlanan ve yaşam öyküsünü şairane bir üslupla anlattığı anı kitabının adı nedir?', 'Yaşadığımı İtiraf Ediyorum', ['Kara Ada Günlükleri', 'Yalnızlığın Dolambacı', 'Balık ve Dalga Anıları'], 'Özgün adı "Confieso que he vivido" olan "Yaşadığımı İtiraf Ediyorum", Neruda\'nın çocukluğundan İspanya İç Savaşı\'na, sürgün yıllarından Nobel\'e uzanan anılarını içerir.'),
  ('Mario Vargas Llosa\'nın 19. yüzyıl sonunda Brezilya\'nın kurak Canudos bölgesinde kıyametçi vaiz Antônio Conselheiro etrafında toplanan yoksulların cumhuriyet ordusuyla çatışmasını destanlaştırdığı romanı hangisidir?', 'Dünyanın Sonu Savaşı', ['Cennet Başka Yerde', 'Kelt Rüyası', 'Mayta\'nın Öyküsü'], 'Euclides da Cunha\'nın klasik incelemesi "Os Sertões"ten esinlenen 1981 tarihli "Dünyanın Sonu Savaşı" (La guerra del fin del mundo), bağnazlık, ideoloji ve devlet şiddetini çarpıştırır.'),
  ('"Pedro Páramo" romanında kasabanın acımasız derebeyi Pedro Páramo\'nun çocukluğundan beri saplantılı bir aşkla bağlandığı, ancak deliliğe sığınarak onun iktidarına teslim olmayan kadın kimdir?', 'Susana San Juan', ['Eduviges Dyada', 'Damiana Cisneros', 'Dorotea'], 'Pedro Páramo\'nun tüm zulmüne rağmen ruhuna asla hükmedemediği Susana San Juan öldüğünde kasabada günlerce çanlar çalar, fakat halk bunu şenliğe çevirince Pedro Páramo Comala\'yı açlığa terk ederek intikam alır.'),
  ('Yaralı oğlu Ignacio\'yu sırtında taşıyarak karanlıkta doktor bulmak için Tonaya kasabasına yürüyen yaşlı bir babanın hem öfke hem şefkat dolu monoloğunu okuyan biri Juan Rulfo\'nun hangi öyküsünü inceliyordur?', 'Köpeklerin Havladığını Duymuyor musun?', ['Beni Öldürmemelerini Söyle Onlara!', 'Luvina', 'Bize Toprak Verdiler'], '"Köpeklerin Havladığını Duymuyor musun?" (¿No oyes ladrar los perros?), haydut olan oğlunu sırtında taşıyan babanın "siz/sen" hitapları arasındaki geçişlerle vicdan ve babalık yükünü yansıttığı başyapıttır.'),
  ('Fernando Pessoa\'nın yakın arkadaşı Mário de Sá-Carneiro\'ya yazdığı ünlü mektupta Alberto Caeiro, Ricardo Reis ve Álvaro de Campos\'un aynı anda zihninde doğduğunu belirttiği "zafer günü" hangi tarihtir?', '8 Mart 1914', ['13 Haziran 1888', '30 Kasım 1935', '5 Ekim 1910'], 'Pessoa, 13 Ocak 1935 tarihli ünlü mektubunda 8 Mart 1914 gününü "hayatımın zafer günü" olarak tanımlar ve yüksek bir şifonyerin başında ayakta durarak "Sürü Güdücüsü"nün otuz küsur şiirini bir çırpıda yazdığını anlatır.'),
  ('Fernando Pessoa\'nın Alberto Caeiro kimliğiyle yazdığı "Bir çiçeğin gizli anlamı yoktur / Bir taşın ne içi vardır ne dışı" yaklaşımı hangi edebi eğilime kökten bir karşı çıkıştır?', 'Doğadaki varlıklara sürekli mistik, sembolist ve metafizik anlamlar yükleyen simgeci-romantik şiir geleneğine', ['Nesneleri yalnızca geometrik küp ve konilere indirgeyen Fransız kübist resim anlayışına', 'Köylülerin tarımsal üretim araçlarını gerçekçi biçimde betimleyen natüralist köy romanına', 'Sözcüklerin etimolojik köklerini araştıran tarihsel dilbilim çalışmalarına'], 'Caeiro\'nun "mutlak nesnellik" ve "görmeyi öğrenmek" felsefesi, varlıkları başka bir hakikatin şifresi sayan sembolizme ve mistisizme radikal bir reddiyedir: "Düşünmek gözlerin hasta olmasıdır."'),
  ('Fernando Pessoa ve Mário de Sá-Carneiro öncülüğünde 1915 yılında yalnızca iki sayı çıkmasına karşın Portekiz edebiyatında modernizmi başlatan avangart derginin adı nedir?', 'Orpheu', ['Presença', 'Seara Nova', 'Águia'], '1915\'te yayımlanan "Orpheu" dergisi, Portekiz\'de muhafazakar edebiyat çevrelerinde skandal yaratmış ve Portekiz modernizminin ("Orpheu Kuşağı") doğuş belgesi olmuştur.'),
  ('José Saramago\'nun "Mağara" (A Caverna) romanında geleneksel çömlekçi Cipriano Algor\'un dev alışveriş ve yaşam merkezi "Merkez" karşısındaki yenilgisi hangi klasik felsefi metinle doğrudan diyalog kurar?', 'Platon\'un "Devlet" adlı eserindeki gerçeklik ile gölgeler dünyasını karşılaştıran Mağara Alegorisi\'yle', ['Aristoteles\'in "Nikomakhos\'a Etik" eserindeki altın orta ve erdemli yurttaş öğretisiyle', 'Thomas More\'un özel mülkiyetin kaldırıldığı ada toplumunu anlatan "Ütopya" metniyle', 'Descartes\'ın "Yöntem Üzerine Konuşma" kitabındaki analitik geometri ilkeleriyle'], 'Cipriano Algor, dev alışveriş merkezinin bodrum kazısında birbirine zincirlenmiş taşlaşmış insan cesetleri bulduğunda, yapay tüketim cenneti "Merkez"in aslında Platon\'un mağarasının ta kendisi olduğunu anlar.'),
  ('José Saramago\'nun 16. yüzyılda Portekiz Kralı III. João\'nun Avusturya Arşidükü Maximilian\'a düğün hediyesi olarak Lizbon\'dan Viyana\'ya gönderdiği Süleyman adlı Asya filinin serüvenini anlattığı romanı hangisidir?', 'Filin Yolculuğu', ['Kabil', 'Umut Tarlaları', 'Mızrak Ucu'], '2008 tarihli "Filin Yolculuğu" (A Viagem do Elefante), fil Süleyman ile Hintli bakıcısı Subhro\'nun Alpleri aşarak Viyana\'ya uzanan gerçek tarihsel yolculuğunu ince bir mizahla anlatır.'),
  ('José Saramago\'nun "İsa\'ya Göre İncil" (O Evangelho Segundo Jesus Cristo) ve son romanı "Kabil"de (Caim) kutsal metin anlatılarını yeniden kurgularken benimsediği etik-felsefi tutum nasıl özetlenebilir?', 'Kutsal anlatılardaki mutlak otorite ve acımasız yazgı anlayışını insani vicdan, merhamet ve özgür irade açısından sorgulayan hümanist bir eleştiri', ['Orta Çağ manastırlarındaki Latince ilahileri sadakatle Portekizce hece ölçüsüne aktaran ortodoks bir savunu', 'Tarihsel olayları tamamen doğa bilimleri ve arkeolojik karbon testleriyle kanıtlama girişimi', 'Doğu mistisizmi ile Antik Mısır çoktanrıcılığını birleştirerek yeni bir tarikat kurma çabası'], 'Saramago her iki romanda da acı çeken sıradan insanın yanında durarak geleceğin kanlı din savaşlarını ve masumların cezalandırılmasını insani adalet terazisinde sorgular.'),
  ('Octavio Paz\'ın aşk, cinsellik ve erotizm kavramlarının Batı edebiyatı ve düşünce tarihindeki dönüşümünü Platon\'dan çağdaş bilime uzanarak incelediği 1993 tarihli ünlü deneme kitabı hangisidir?', 'Çifte Alev', ['Yay ve Lir', 'Yalnızlığın Dolambacı', 'Çamur Çocuklar'], '"Çifte Alev: Aşk ve Erotizm" (La llama doble), cinselliği hayvani temel, erotizmi insanileşmiş hayal gücü ve aşkı ise tek bir özgür kişiye yönelen "mavi alev" olarak çözümler.'),
  ('Juan Rulfo\'nun "Luvina" adlı öyküsünde yüksek, rüzgarlı ve kireçli bir dağ köyünden yeni dönen yaşlı öğretmenin, oraya yeni atanan genç meslektaşına meyhanede anlattığı monolog nasıl bir atmosfer kurar?', 'Zamanın donduğu, rüzgarın umutları kazıdığı ve yalnızca ölülerini bekleyen yaşlıların kaldığı Luvina\'yı araf benzeri bir umutsuzluk mekanı olarak resmeder', ['Genç öğretmeni köyde modern bir tarım kooperatifi kurması için coşkulu devrim marşlarıyla yüreklendirir', 'Köydeki gizli gümüş madeninin haritasını vererek ikisinin birlikte zengin olma planını detaylandırır', 'Luvina halkının İspanyolcadan tamamen farklı neşeli bir karnaval kültürü yarattığını mizahi fıkralarla anlatır'], '"Pedro Páramo"daki Comala\'nın öncüsü kabul edilen "Luvina", kara taşların, acı rüzgarın ve hükümetin yalnızca suçluları cezalandırmak için hatırladığı terk edilmiş Meksika köylerinin şiirsel ağıtıdır.'),
  ('José Saramago\'nun "Görmek" romanında beyaz oy kullanan halka karşı hükümetin kenti terk ederek başkenti kuşatması ve olağanüstü hal ilan etmesi siyaset felsefesi bakımından neyi teşhir eder?', 'Temsili iktidar aygıtlarının kendi meşruiyetini sorgulayan barışçıl ve sessiz sivil iradeyi bile tehlikeli bir "terör komplosu" olarak damgalama eğilimini', ['Seçmenlerin oy pusulalarındaki basım hatası yüzünden yanlışlıkla boş kağıtları sandığa attığını', 'Komşu devletlerin başkenti ele geçirmek için sandık görevlilerine gizlice rüşvet dağıttığını', 'Kent halkının monarşiyi geri getirmek amacıyla silahlı bir darbe hazırlığı içinde olduğunu'], 'Hiçbir şiddet eylemi olmamasına ve halk günlük düzenini barış içinde sürdürmesine rağmen hükümet, iktidar tekelini sarsan sessiz "görme/aydınlanma" eylemine komplo teorileri ve devlet şiddetiyle yanıt verir.'),
  ('Fernando Pessoa\'nın İngiliz sömürgesi altındaki Güney Afrika\'da (Durban) İngilizce eğitim alarak büyüdüğü gençlik yıllarında İngilizce şiir ve öyküler yazmak için yarattığı en önemli erken dönem heteronimi kimdir?', 'Alexander Search', ['Bernardo Soares', 'Alberto Caeiro', 'António Mora'], '1896-1905 yılları arasında üvey babasının konsolosluk görevi nedeniyle Durban\'da yaşayan Pessoa, ana dili düzeyinde hakim olduğu İngilizceyle "Alexander Search" heteronimi altında yoğun eserler üretmiştir.'),
  ('Fernando Pessoa\'nın heteronimleri arasındaki felsefi sistemi kuramsallaştırmak üzere yarattığı, akıl hastanesinde yaşayan ve Hristiyan uygarlığına karşı "neopaganizm"i savunan filozof heteronimi kimdir?', 'António Mora', ['Vicente Guedes', 'Barão de Teive', 'Coelho Pacheco'], 'António Mora, Alberto Caeiro ve Ricardo Reis\'in şiirsel paganizmini felsefi düzlemde savunan kuramcı heteronimdir; Barão de Teive ise intihar etmeden önce tek elyazması bırakan stoacı soylu heteronimdir.'),
  ('Pablo Neruda\'nın 1952 yılında İtalya\'nın Capri Adası\'nda sürgündeyken Matilde Urrutia için yazdığı ve başlangıçta o sıradaki eşini üzmemek için imzasız (anonim) olarak yayımladığı tutkulu aşk şiirleri kitabı hangisidir?', 'Kaptanın Dizeleri', ['Yirmi Aşk Şiiri ve Umutsuz Bir Şarkı', 'Yüz Aşk Sonesi', 'Yeryüzünde Konaklama'], '"Kaptanın Dizeleri" (Los versos del capitán), 1952\'de Napoli\'de yalnızca 44 nüsha halinde anonim basılmış, Neruda kitabı kendi adıyla ancak 1963\'te resmen üstlenmiştir.'),
  ('Juan Rulfo\'nun senaryo taslağı olarak yazdığı, şans getiren yaralı bir dövüş horozu sayesinde servet kazanan Dionisio Pinzón ile panayır şarkıcısı Bernarda ("La Caponera") arasındaki tutkuyu ve kumar yıkımını anlatan kısa romanı hangisidir?', 'Altın Horoz', ['Pedro Páramo', 'Ova Alev Alev', 'Luvina'], '1950\'lerin sonunda yazılıp 1980\'de kitap olarak yayımlanan "Altın Horoz" (El gallo de oro), sinemaya uyarlanmak üzere Gabriel García Márquez ve Carlos Fuentes\'in de senaryo katkısıyla beyazperdeye aktarılmıştır.'),
  ('Latin Amerika "Boom" yazarları ile Portekizce edebiyatın devleri Pessoa ve Saramago\'nun 20. yüzyıl dünya edebiyatına ortak tarihsel katkısı hangi ifadeyle en doğru biçimde değerlendirilebilir?', 'Avrupa-merkezci gerçekçi roman ve tekil özne kalıplarını kırarak zamanı, kimliği, tarihi ve dili çoğulcu bir kurmaca bilinciyle yeniden tanımlamaları', ['Edebiyatı yalnızca on dokuzuncu yüzyıl Fransız doğalcılığının laboratuvar kurallarına sadık kalarak belgesel tutanaklara indirgemeleri', 'Şiir ve romanda toplumsal ve felsefi tüm soruları dışlayarak yalnızca kır manzaraları betimleyen pastoral metinler üretmeleri', 'İspanyolca ve Portekizce dillerindeki yerel deyişleri tamamen temizleyip küresel ticaret İngilizcesine yakın tek tip bir dil kurmaları'], 'Borges\'in sonsuzluk labirentlerinden Márquez\'in büyülü gerçekçiliğine, Pessoa\'nın çoğul benliklerinden Saramago\'nun alegorik sözlü üslubuna kadar bu yazarlar modern edebiyatın sınırlarını kökten genişletmiştir.'),
  ('Fernando Pessoa\'nın ölümünün ardından Lizbon\'daki evinde bulunan ve içinden yirmi beş binden fazla elyazması, şiir, felsefe notu ve heteronim mektubu çıkan ünlü eşya edebiyat tarihinde nasıl anılır?', 'Pessoa\'nın Sandığı', ['Lizbon Kütüphanesi\'nin Demir Kasası', 'Douradores Sokağı\'nın Bakır Çantası', 'Orpheu Dergisi\'nin Deri Bavulu'], 'Pessoa 1935\'te öldüğünde ardında yirmi beş binden fazla kağıt parçasının tıkıştırıldığı ünlü ahşap sandığını (Arca de Pessoa) bırakmış, araştırmacılar onlarca yıl bu sandıktaki hazineyi tasnif etmiştir.'),
  ('Knut Hamsun\'un "Açlık" romanındaki başkahramanın, aşık olduğu genç kadına kendi zihninde taktığı gizemli ve kurgusal isim nedir?', 'Ylajali', ['Viktoria', 'Rebekka', 'Solveig'], '"Açlık" romanının isimsiz anlatıcısı, karşılaştığı genç kadına hayal dünyasında "Ylajali" adını verir.'),
  ('Knut Hamsun\'un "Pan" romanında Teğmen Thomas Glahn\'ın Nordland ormanlarındaki yaşamı ile Edvarda\'ya duyduğu çelişkili aşk hangi temel çatışmayı simgeler?', 'Yabanıl doğa özgürlüğü ile burjuva toplumunun kısıtlayıcı kuralları arasındaki uyuşmazlığı', ['Askeri disiplin anlayışı ile köylülerin geleneksel tarım yöntemleri arasındaki çekişmeyi', 'Kuzey mitolojisindeki tanrı inancı ile Hristiyanlık misyonerliği arasındaki tarihsel kavgayı', 'Sanayi Devrimi\'nin fabrika düzeni ile deniz ticareti loncaları arasındaki ekonomik rekabeti'], 'Teğmen Glahn doğanın içgüdüsel özgürlüğünü temsil ederken, Edvarda ile ilişkisi uygar toplumun yapaylığıyla çatışır.'),
  ('Knut Hamsun\'un "Açlık" romanının 20. yüzyıl modernist edebiyatına yaptığı en önemli biçimsel ve teknik katkı aşağıdakilerden hangisidir?', 'Bilinç akışı ve iç monolog tekniklerinin erken bir öncüsü olarak öznel gerçekliği merkeze alması', ['Çok katmanlı tarihsel belgeleri gazete kupürleriyle birleştirerek belgesel roman türünü kurması', 'Köylü ağızlarını ve yerel diyalektleri fonetik alfabeyle kayda geçirerek doğalcılığı zirveye taşıması', 'Olay örgüsünü tamamen mektuplar üzerinden kurgulayarak klasik epistolary geleneğini canlandırması'], 'Hamsun, dışsal olaylardan ziyade açlığın zihinde yarattığı sanrıları ve bilinç dalgalanmalarını aktararak modernizme öncülük etmiştir.'),
  ('Selma Lagerlöf\'ün Värmland bölgesinin yerel efsanelerinden beslenerek yazdığı ve görevden alınmış karizmatik bir rahibin etrafındaki "on iki şövalyeyi" anlatan ilk romanı hangisidir?', 'Gösta Berling Efsanesi', ['Löwensköld Yüzüğü', 'Kudüs', 'Çobanın Kızı'], '1891\'de yayımlanan "Gösta Berling Efsanesi" (Gösta Berlings saga), Lagerlöf\'ün neo-romantik tarzdaki ilk büyük yapıtıdır.'),
  ('Selma Lagerlöf\'ün "Kudüs" (Jerusalem) adlı iki ciltlik romanında Dalarna bölgesindeki İsveçli köylülerin topraklarını satıp Kutsal Topraklar\'a göç etmesi hangi gerilimi irdeler?', 'Kök salınmış ata toprağına bağlılık ile radikal dini uyanış hareketlerinin yarattığı kopuş arasındaki çatışmayı', ['Sanayileşen başkent Stockholm\'ün işçi göçü ile kırsal kesimdeki madencilik şirketleri arasındaki rekabeti', 'İsveç Kraliyet Kilisesi\'nin vergi politikaları ile gezgin tüccarların gümrük ayrıcalıkları arasındaki anlaşmazlığı', 'Kuzey kutup dairesindeki iklim değişiklikleri ile Akdeniz tarım ürünlerine duyulan ticari özlem arasındaki bağı'], 'Gerçek bir olaya dayanan "Kudüs", dini coşkuyla geleneksel çiftliklerini terk eden köylülerin yaşadığı manevi ve maddi sarsıntıyı işler.'),
  ('Hans Christian Andersen\'in yalnızca bir masal yazarı değil aynı zamanda romancı olduğunu gösteren, İtalya\'daki genç sanatçı Antonio\'nun yaşamını anlattığı ilk başarılı romanı hangisidir?', 'Doğaçlamacı', ['Sadece Bir Kemancı', 'İki Barones', 'Olacak mı Olmayacak mı'], '1835 tarihli "Doğaçlamacı" (Improvisatoren), Andersen\'in İtalya seyahatinden esinlenerek yazdığı yarı-otobiyografik romanıdır.'),
  ('Andersen\'in "Gölge" (Skyggen) adlı karanlık felsefi masalında bilgin bir adamın gölgesinin bedenden ayrılıp efendisini köleleştirmesi neyi alegorize eder?', 'Yüzeysel taklit ve güç hırsının hakiki entelektüel değerleri alt ederek insanın özünü yok etmesini', ['Aydınlanma Çağı bilim insanlarının optik deneyler sırasında doğa yasalarına karşı işlediği günahları', 'Romantik dönem şairlerinin ikiz kardeş motifini kullanarak kalıtımsal hastalıkları açıklama gayretini', 'Sömürge valilerinin uzak diyarlardaki ticaret tekellerini ele geçirerek anavatana başkaldırmasını'], '"Gölge" masalında gerçek bilgi ve iyiliği temsil eden bilgin, dış görünüşü ve kurnazlığı kullanan kendi gölgesinin kurbanı olur.'),
  ('İvo Andrić\'in Napolyon savaşları döneminde Bosna\'nın vezirlik merkezine atanan Fransız konsolos Jean Daville ile Avusturyalı mevkidaşının yıllarını anlattığı roman hangisidir?', 'Travnik Kronikleri', ['Lanetli Avlu', 'Matmazel', 'Ömer Paşa Latas'], '"Bosna Hikâyesi" olarak da bilinen "Travnik Kronikleri" (Travnička hronika), konsolosluklar döneminde Doğu-Batı karşılaşmasını işler.'),
  ('İvo Andrić\'in İstanbul\'daki bir hapishanede geçen "Lanetli Avlu" (Prokleta avlija) adlı uzun öyküsünde Boşnak rahip Fra Petar ile İzmirli genç Kamil arasındaki ilişki neyi ortaya koyar?', 'Baskıcı iktidar mekanizmalarının masum bireyleri tarihsel paranoyalar ve kimlik yanılsamaları üzerinden nasıl öğüttüğünü', ['Osmanlı donanmasındaki denizcilerin Akdeniz korsanlarına karşı geliştirdiği savunma stratejilerinin başarısızlığını', 'Balkan manastırlarındaki el yazması eserlerin Batılı oryantalistler tarafından kaçırılmasının yarattığı kültürel yıkımı', 'Tanzimat Fermanı sonrasında İstanbul\'daki esnaf loncalarının modern mahkemelere uyum sağlama sürecindeki zorlukları'], 'Sultan Cem\'in hayatına duyduğu akademik ilgi yüzünden şüpheli sayılan Kamil\'in trajedisi, iktidarın paranoyasını ve insanın yalnızlığını simgeler.'),
  ('Nikos Kazancakis\'in Birinci Dünya Savaşı sonrası Anadolu\'da Rum köylülerinin İsa\'nın çilesini canlandıran bir piyes hazırlarken mültecilerin gelişiyle bu rolleri gerçekten yaşamalarını anlatan romanı hangisidir?', 'Yeniden Çarmıha Gerilen İsa', ['Günaha Son Çağrı', 'Kaptan Mihalis', 'Allah\'ın Fukarası'], '"Yeniden Çarmıha Gerilen İsa" (O Hristos Ksanastavronetai), Likovrisi köyündeki Paskalya temsili üzerinden ahlaki ikiyüzlülüğü ve fedakârlığı işler.'),
  ('Kazancakis\'in "Zorba" romanında kitaplara gömülmüş "Patron" (Anlatıcı) ile okuma yazmayı değil hayatı doğrudan deneyimleyen Zorba arasındaki karşıtlık hangi felsefi ikiliğe dayanır?', 'Soyut ve edilgen entelektüel akıl (Apolloncu) ile bedensel coşku ve eylem (Dionizyak) arasındaki tamamlayıcı gerilime', ['Platon\'un idealar dünyası öğretisi ile Orta Çağ skolastik teolojisinin dogmatik kuralları arasındaki uyuma', 'Marksist sınıf bilinci kuramı ile feodal toprak ağalığının ataerkil gelenekleri arasındaki tarihsel çatışmaya', 'Stoacı kaderci boyun eğiş ile Epikürcü toplumdan tamamen inzivaya çekilme ahlakı arasındaki benzerliğe'], 'Kazancakis, Buda üzerine yazılar yazan çekingen aydın ile hayatı et ve kemik olarak yaşayan Zorba üzerinden düşünce-eylem çatışmasını kurar.'),
  ('İsmail Kadare\'nin totaliter iktidarların insan bilinçaltını bile denetleme arzusunu Osmanlı başkentindeki kurgusal bir devlet kurumu üzerinden alegorik biçimde eleştirdiği başyapıtı hangisidir?', 'Rüyalar Sarayı', ['Üç Kemerli Köprü', 'Kırık Nisan', 'Nişancı'], '1981\'de yayımlanıp Enver Hoca rejimince yasaklanan "Rüyalar Sarayı" (Pallati i Ëndrrave), "Tabir Sarayı" aracılığıyla totalitarizmi taşlar.'),
  ('İsmail Kadare\'nin doğduğu Ergiri (Gjirokastër) kentini İkinci Dünya Savaşı yıllarında bir çocuğun gözünden anlattığı "Taş Kentin Kroniği"nde "taş" imgesi neyi temsil eder?', 'Sürekli el değiştiren işgal ordularına karşı kentin kadim belleğini, direncini ve sarsılmaz kimliğini', ['Arnavutluk ekonomisinin yalnızca mermer ve granit ihracatına dayalı tek yönlü kalkınma modelini', 'Köylülerin modern apartman mimarisine geçmek için tarihi binaları yıkma konusundaki aşırı istekliliğini', 'Balkan yarımadasındaki volkanik patlamaların tarım arazilerini çoraklaştırarak göçe zorlamasını'], 'Dik yamaçlı, taş çatılı Ergiri kenti; İtalyan, Yunan ve Alman işgalleri karşısında taşlaşmış tarihsel direncin sembolüdür.'),
  ('Amin Maalouf\'a 1993 yılında Fransa\'nın en prestijli edebiyat ödülü olan Goncourt Ödülü\'nü kazandıran ve 19. yüzyıl Lübnan dağlarındaki bir efsaneyi işleyen romanı hangisidir?', 'Tanios Kayası', ['Doğunun Limanları', 'Semerkant', 'Yolların Başlangıcı'], '"Tanios Kayası" (Le Rocher de Tanios), Maalouf\'a Prix Goncourt\'u getiren ve Lübnan\'daki yerel iktidar ile dış müdahaleleri anlatan eseridir.'),
  ('Amin Maalouf\'un İkinci Dünya Savaşı sırasında Fransız Direniş Örgütü\'nde tanışan Osmanlı hanedanından bir kadının oğlu Ossyane ile Yahudi kızı Clara\'nın 1948 Arap-İsrail Savaşı\'yla bölünen aşkını anlattığı romanı hangisidir?', 'Doğunun Limanları', ['Semerkant', 'Empedokles\'in Dostları', 'Doğudan Uzakta'], '"Doğunun Limanları" (Les Échelles du Levant), hoşgörü ikliminden savaş ve sınırların ayırdığı dünyaya düşen Ossyane ile Clara\'nın öyküsüdür.'),
  ('Amin Maalouf\'un 3. yüzyıl Mezopotamya\'sında hoşgörü ve sanat merkezli bir inanç kuran peygamber Mani\'nin yaşamını ve trajik sonunu işlediği romanı hangisidir?', 'Işık Bahçeleri', ['Yüzüncü Ad', 'Afrikalı Leo', 'Semerkant'], '"Işık Bahçeleri" (Les Jardins de Lumière), Maniheizm\'in kurucusu Mani\'nin Sasani İmparatorluğu\'ndaki yaşamını anlatır.'),
  ('Necib Mahfuz\'un "Kahire Üçlemesi"nde evde ailesine karşı son derece katı, otoriter ve dindar davranırken dışarıda eğlence meclislerinin aranan ismi olan baba Seyyid Ahmed Abdülcevad neyi simgeler?', 'Geleneksel ataerkil otoritenin çifte standardını ve modernleşme arifesindeki Mısır toplumunun içsel çelişkilerini', ['İngiliz sömürge idaresine karşı kurulan gizli askeri istihbarat örgütlerinin kusursuz kamuflaj yöntemlerini', 'Ezher Üniversitesi müderrislerinin Batı felsefesini Mısır eğitim sistemine uyarlama konusundaki öncü çabalarını', 'Kahire\'deki sanayi burjuvazisinin kırsal kesimdeki pamuk üreticileriyle kurduğu eşitlikçi ticaret ortaklığını'], 'Seyyid Ahmed Abdülcevad\'ın ev içi despotizmi ile ev dışı hazcı yaşamı, ataerkil yapının ikiyüzlülüğünü ustalıkla sergiler.'),
  ('Necib Mahfuz\'un tek bir malikâne ve çevresinde geçen, Adem\'den modern bilime kadar peygamberler ve insanlık tarihini alegorik bir mahalle kavgası şeklinde kurguladığı tartışmalı romanı hangisidir?', 'Cebelavi Sokağının Çocukları', ['Nil Üstünde Gevezelik', 'Muhterem Efendi', 'İbn Fattuma\'nın Yolculuğu'], '"Cebelavi Sokağının Çocukları" (Evladu Haretina); Cebelavi, Adham, Cebel, Rıfat, Kasım ve Arafe karakterleriyle dinler ve bilim tarihini alegorileştirir.'),
  ('Necib Mahfuz\'un hapisten çıktıktan sonra kendisini ihbar eden eski karısı ve dostundan intikam almak isterken trajik biçimde kuşatılan Said Mehran adlı karakteri anlattığı varoluşçu romanı hangisidir?', 'Hırsız ve Köpekler', ['Bıldırcın ve Sonbahar', 'Başlangıç ve Son', 'Harafiş'], '1961 tarihli "Hırsız ve Köpekler" (el-Liss ve\'l-Kilab), 1952 Mısır Devrimi sonrasındaki hayal kırıklığını bilinç akışı tekniğiyle işler.'),
  ('Knut Hamsun\'un İkinci Dünya Savaşı sonrasında vatana ihanet suçlamasıyla psikiyatri kliniğinde ve huzurevinde tutulduğu sırada 90 yaşında yayımladığı son anı-savunma kitabı hangisidir?', 'Ot Büyüdü Patikalarda', ['Serserilik Günleri', 'Çağın Çocukları', 'Kadınlar Çeşmesi'], '1949\'da yayımlanan "Ot Büyüdü Patikalarda" (På gjengrodde stier), Hamsun\'un gözaltı günlerini ve edebi yeteneğinin sönmediğini gösteren son eseridir.'),
  ('Nikos Kazancakis\'in Homeros\'un ünlü destanını kaldığı yerden devam ettirerek İthaka\'dan ayrılan kahramanın Afrika ve Antarktika\'ya uzanan felsefi yolculuğunu 33.333 dizede anlattığı dev şiiri hangisidir?', 'Odysseia', ['Çileci', 'Yılan ve Zambak', 'Toda Raba'], 'Kazancakis kendi başyapıtı saydığı modern "Odysseia" destanını tam 33.333 dizeden oluşan devasa bir felsefi epik olarak kurgulamıştır.'),
  ('Amin Maalouf\'un 1666 ("Canavar Yılı") arifesinde İzmir ve Lübnan\'dan Londra\'ya uzanan bir yolculukta "Mazandarani\'nin Kitabı" adlı gizemli bir eserin peşine düşen Cenevizli sahaf Baldassare\'yi anlattığı romanı hangisidir?', 'Yüzüncü Ad', ['Tanios Kayası', 'Afrikalı Leo', 'Yolların Başlangıcı'], '"Yüzüncü Ad: Baldassare\'nin Yolculuğu", kıyamet söylentilerinin yayıldığı 1666 yılına girerken bilgelik ve hurafe çatışmasını işler.'),
  ('Necib Mahfuz\'un İbn Battuta\'nın seyahatnamesinden esinlenerek, mükemmel ve adil toplumu bulmak amacıyla Darü\'l-Cebel\'den Darü\'l-Gurub\'a dek farklı ülkeleri gezen bir gezgini anlattığı felsefi romanı hangisidir?', 'İbn Fattuma\'nın Yolculuğu', ['Binbir Gecenin Geceleri', 'Harafiş', 'Ahenaton'], '"İbn Fattuma\'nın Yolculuğu", İslam dünyasından sosyalist ve kapitalist toplum modellerine kadar farklı rejimleri sorgulayan alegorik bir yolculuktur.'),
  ('Knut Hamsun\'un "Toprağın Bereketi" romanında İsak\'ın ıssız doğada tek başına kazma vurarak başlattığı çiftlik yaşamına telgraf hattı ve madencilerin gelmesi yazar tarafından nasıl değerlendirilir?', 'İnsanı toprağın sahici üretiminden koparan modern ticaret ve spekülasyon kültürünün yozlaştırıcı bir tehdidi olarak', ['Kuzey Norveç köylülerinin yoksulluktan kurtulmasını sağlayan kaçınılmaz ve ilerici bir sanayi devrimi olarak', 'İskandinav ülkeleri arasındaki siyasi birliği hızlandıran demokratik bir iletişim mucizesi olarak', 'Doğadaki vahşi hayvan popülasyonunu kontrol altına alan bilimsel bir çevre koruma hamlesi olarak'], 'Hamsun moderniteye, sanayiye ve kentli spekülasyona kuşkuyla yaklaşır; gerçek bereketi ve ahlakı İsak\'ın toprağa bağlı emeğinde görür.'),
  ('Nikos Kazancakis\'in Hristiyan azizi Assisili Francesco\'nun yoksulluk, doğa sevgisi ve tanrıya ulaşma yolundaki çileli yaşamını Kardeş Leo\'nun ağzından anlattığı romanı hangisidir?', 'Allah\'ın Fukarası', ['Günaha Son Çağrı', 'Kardeş Kavgası', 'Zorba'], '"Allah\'ın Fukarası" (O Ftohoulis tou Theou), Assisili Francesco\'nun maddi dünyayı reddederek ruhsal yüceliğe tırmanışını konu alır.'),
  ('İvo Andrić, İsmail Kadare ve Amin Maalouf\'un tarihsel roman anlayışlarını buluşturan en temel edebi ortak payda aşağıdakilerden hangisidir?', 'Çok kültürlü imparatorluk coğrafyalarındaki geçmiş olayları insan doğasının evrensel iktidar, kimlik ve hoşgörü sorunlarını aydınlatan bir ayna olarak kullanmaları', ['Tarihsel gerçekliği tamamen reddederek uzay çağında geçen bilimkurgu ütopyaları inşa etmeleri', 'Yalnızca tek bir ulusun askeri zaferlerini yücelten didaktik kahramanlık destanları kaleme almaları', 'Geleneksel anlatı zamanını terk ederek yalnızca yirmi dört saatlik tek mekân tiyatro metinleri üretmeleri'], 'Üç yazar da Balkanlar ve Orta Doğu\'nun çok katmanlı tarihini şovenizmden uzak, trajik ve felsefi bir insanlık panoraması olarak kurgulamıştır.'),
  ('Cengiz Aytmatov\'un "Gün Olur Asra Bedel" romanında Nayman Ana\'nın vurulurken başından düşen beyaz yazmasının dönüştüğü ve bozkırda "Baban kim? Adın ne?" diye ötüp duran efsanevi kuşun adı nedir?', 'Dönenbay', ['Hüma', 'Zümrütanka', 'Kızıl Şahin'], 'Nayman Ana\'nın yazması "Dönenbay" kuşuna dönüşür ve bozkır yolcularına babası Dönenbay\'ın adını haykırarak hafıza çağrısı yapar.'),
  ('"Gün Olur Asra Bedel" romanında Kazangap\'ın yatılı okullarda okuyup şehirli bürokrat olan oğlu Sabitcan\'ın cenazeye karşı ilgisizliği ve Ana-Beyit mezarlığının uzay üssü tel örgüleriyle kapatılması nasıl bir paralellik kurar?', 'Geleneksel mankurt efsanesinin modern çağda ideolojik şartlandırma ve teknokratik bellek yıkımıyla yeniden üretildiğini gösterir', ['Uzay araştırmalarının Kırgız bozkırındaki tarımsal sulama kanallarını kısa sürede modernleştirdiğini kanıtlar', 'Demiryolu işçilerinin emeklilik haklarının şehirdeki genç bürokratlar tarafından başarıyla savunulduğunu ortaya koyar', 'Eski mezarlık alanlarının arkeolojik sit alanı ilan edilerek turizme açılmasının ekonomik faydalarını vurgular'], 'Sabitcan modern bir mankurttur; uzay üssünün kutsal Ana-Beyit mezarlığını yok etmesi ise köklerden koparılmanın teknolojik yüzüdür.'),
  ('"Gün Olur Asra Bedel" romanında çocukları için halk türkülerini ve savaş anılarını kaleme aldığı gerekçesiyle sürgün istasyonunda tutuklanıp ölüme gönderilen öğretmen kimdir?', 'Abutalip Kuttubayev', ['Zarife', 'Tansıkbayev', 'Çorayev'], 'Stalin döneminin baskı atmosferinde geçmişi hatırlamanın bile suç sayıldığı ortamda Abutalip, çocuklarına anı yazdığı için kurban edilir.'),
  ('"Selvi Boylum Al Yazmalım" eserinde İlyas\'ın aşırı özgüveni yüzünden römorklu kamyonla aşmaya çalışırken kaza yaptığı ve hayatının altüst olmasına yol açan tehlikeli dağ geçidi neresidir?', 'Dolon Geçidi', ['Tanrı Dağları Geçidi', 'Pamir Boğazı', 'Fergana Vadisi'], 'Tanrı Dağları\'ndaki sarp ve karlı "Dolon Geçidi", İlyas\'ın mesleki kibrinin ve içsel savrulmasının kırılma noktasıdır.'),
  ('"Beyaz Gemi" romanında zalim enişte Orozkul\'un zoruyla Mümin Dede\'nin kutsal saydığı maralı vurup etini pişirmeleri üzerine küçük çocuğun kendini nehre bırakması neyi ifade eder?', 'Masumiyetin ve kutsal değerlerin yetişkinlerin zorbalığıyla kirletildiği bir dünyada kötülüğe teslim olmaktansa masalına sığınarak arınmayı', ['Issık Gölü\'ndeki balıkçı teknelerine gizlice binerek büyük şehirde yatılı okula gitme konusundaki çocukça kararlılığı', 'Orman koruma memurlarını uyarmak amacıyla nehir suyunun akış yönünü takip ederek kasabaya haber ulaştırma çabasını', 'Kış mevsimi gelmeden yüzme antrenmanlarını tamamlayarak denizcilik okuluna kabul edilme arzusunu'], 'Çocuk, dedesinin bile Orozkul\'a boyun eğip Boynuzlu Maral Ana\'yı öldürdüğünü görünce bu kirli gerçekliği reddeder ve "balık olma" masalına yürür.'),
  ('Cengiz Aytmatov\'un Moyunkum bozkırında yaşayan mavi gözlü kurt çifti Akbara ile Taşçaynar\'ın doğa katliamı ve insan açgözlülüğü karşısındaki trajedisini anlattığı ekolojik ve felsefi romanı hangisidir?', 'Dişi Kurdun Rüyaları', ['Gün Olur Asra Bedel', 'Ebedi Gelin', 'Deniz Kıyısında Koşan Ala Köpek'], '"Kıyamet" (Plaha) adıyla da çevrilen "Dişi Kurdun Rüyaları", Akbara ve Taşçaynar\'ın yavrularını kaybetmesiyle Avdiy ve Boston\'un öykülerini birleştirir.'),
  ('Cengiz Aytmatov\'un Ohotsk Denizi\'nde avlanmaya çıkan Nivh (Gilyak) kabilesinden üç yetişkinin, yoğun siste kayboldukları kayıkta küçük Kirisk yaşasın diye kendi canlarını feda etmelerini anlatan eseri hangisidir?', 'Deniz Kıyısında Koşan Ala Köpek', ['Erken Gelen Turnalar', 'Beyaz Gemi', 'Cengiz Han\'a Küsen Bulut'], '"Deniz Kıyısında Koşan Ala Köpek", kısıtlı içme suyunu çocuk Kirisk\'e bırakarak sisli denize atlayan yaşlı Organ, Emrayin ve Mılgun\'un yüce fedakârlığıdır.'),
  ('Cengiz Aytmatov\'un uzaydaki rahip-bilimci Filofey\'in doğmamış bebeklerin alnında dünyaya gelmeyi reddettiklerini gösteren bir işaret keşfetmesini konu alan felsefi-bilimkurgu romanı hangisidir?', 'Kassandra Damgası', ['Ebedi Gelin', 'Dişi Kurdun Rüyaları', 'Beyaz Gemi'], '1995 tarihli "Kassandra Damgası", insanlığın ahlaki çöküşü nedeniyle embriyoların bile dünyaya doğmak istememesi fikri üzerine kuruludur.'),
  ('Bahtiyar Vahabzade\'nin büyük Türk şairi Fuzuli\'nin yaşamını, ıstırabını ve "Leyla ile Mecnun"u yazış sürecini felsefi derinlikle işlediği ünlü poeması hangisidir?', 'Şeb-i Hicran', ['Atılmışlar', 'Özümüzü Kesen Kılıç', 'Feryad'], '"Şeb-i Hicran" (Ayrılık Gecesi), Vahabzade\'nin Fuzuli\'nin aşk ve dert felsefesini merkeze alarak kaleme aldığı en önemli lirik-felsefi poemalarındandır.'),
  ('Bahtiyar Vahabzade\'nin 20 Ocak 1990\'da Sovyet tanklarının Bakü\'de sivil halkı katletmesi üzerine büyük bir acı ve öfkeyle kaleme aldığı destansı şiir-poema hangisidir?', 'Şehitler', ['Latin Dili', 'Kökler ve Budaklar', 'Dar Ağacı'], 'Bakü\'deki "Kara Ocak" (20 Yanvar) katliamında bizzat tankların karşısına dikilen Vahabzade, bu direnişi "Şehitler" poemasıyla ebedileştirmiştir.'),
  ('Bahtiyar Vahabzade\'nin Fas\'ta görev yaptığı sırada gördüğü manzaradan esinlenerek yazdığı "Latin Dili" şiirinde ölü bir dil olan Latincenin yaşaması üzerinden verdiği alegorik mesaj nedir?', 'Sömürgeciliğe boyun eğip ana dilini unutan toplumların kendi ülkelerinde ruhen ölü, ölü sayılan dillerin ise bilimle diri kaldığı', ['Akdeniz ülkelerindeki tıp fakültelerinde Latince terimlerin kullanılmasının eğitim süresini gereksiz yere uzattığı', 'Kuzey Afrika halklarının Fransızca yerine İspanyolca öğrenmesinin ticari ilişkileri hızlandıracağı', 'Antik Roma mimarisinin Fas\'taki İslam eserlerinden estetik bakımdan daha dayanıklı olduğu'], 'Sovyet sansürünü aşmak için Fas ve Fransızca/Latince örneğini kullanan Vahabzade, aslında Bakü\'de Rusça konuşup kendi dilini hor gören aydınları uyarmıştır.'),
  ('Bahtiyar Vahabzade\'nin Azerbaycan geleneksel müziğinin dört ana makamını (Rast, Şur, Segâh, Çargâh) insan ruhunun halleri ve vatan tarihiyle bütünleştirdiği ünlü poeması hangisidir?', 'Muğam', ['Gülistan', 'Ağlar-Güler', 'Kelebek'], '"Muğam" poeması, Azerbaycan\'ın kadim musiki mirasını felsefi ve milli bir kimlik manifestosuna dönüştürür.'),
  ('Gençliğinde tıp fakültesi son sınıf öğrencisiyken yaşadığı büyük ve umutsuz aşk yüzünden okulunu bırakan ve sürgüne gönderilen Şehriyar\'ın şiirlerinde hangi takma adla andığı sevgilisi bu kırılmaya yol açmıştır?', 'Süreyya', ['Şirin', 'Nigâr', 'Zübeyde'], 'Tahran\'da aşık olduğu "Süreyya" (şiirlerinde Peri), dönemin güçlü bir saray paşasının müdahalesiyle kendisinden koparılmış ve Şehriyar\'ın hayatını değiştirmiştir.'),
  ('Gençlik yıllarında "Behcet" mahlasını kullanan şairin, kendi mahlasını "Şehriyar" olarak değiştirmesine vesile olan geleneksel uygulama aşağıdakilerden hangisidir?', 'Şirazlı Hafız\'ın Divan\'ından çektiği tefeülde (falda) iki kez üst üste "Şehriyar" kelimesinin çıkması', ['Tebriz\'deki şairler meclisinde yapılan atışma yarışmasında başhakem tarafından kendisine bu unvanın verilmesi', 'Tıp fakültesindeki anatomi hocasının onun hitabet yeteneğini överek bu soyadını nüfusa kaydettirmesi', 'Osmanlı sarayından Tebriz\'e gönderilen bir fermanla ailesine beylik beratı bağışlanması'], 'Şair, büyük ustası Hafız-ı Şirazi\'nin Divan\'ından fal tutmuş (tefeül) ve çıkan beyitlerde "Şehriyar" sözcüğü belirdiği için bu mahlası benimsemiştir.'),
  ('Şehriyar\'ın "Heyder Babaya Selam" dışında Azerbaycan Türkçesiyle kaleme aldığı, Aras Nehri\'nin kuzeyindeki kardeşlerine duyduğu hasreti ve engelleri dile getirdiği ünlü şiirlerinden biri hangisidir?', 'Seherdiye', ['Hümay ve Hümayun', 'Gülistan Bağı', 'Yedi Güzel'], 'Şehriyar\'ın dostu Bulud Karaçorlu Sehend\'e hitaben yazdığı "Sehendiyye" ve Türkiye\'ye seslendiği "Türkiye\'ye Hayali Sefer" önemli Türkçe şiirlerindendir.'),
  ('Selma Lagerlöf\'ün "Löwensköld Yüzüğü" üçlemesinin ilk kitabında General Löwensköld\'ün mezarından çalınan mühür yüzüğün kuşaklar boyu felaket getirmesi hangi anlatı tekniğine örnektir?', 'Gotik halk efsanesi motifini insan vicdanı, açgözlülük ve suçluluk psikolojisini çözümleyen ahlaki bir çerçeveye dönüştürmeye', ['Polisiye romanlardaki parmak izi ve balistik inceleme yöntemlerini İsveç mahkemelerine tanıtmaya', 'Kraliyet hazinesindeki mücevherlerin ekonomik değerini enflasyon oranlarıyla karşılaştırmaya', 'Doğaüstü korku öğelerini tamamen alaya alarak parodi türünde komik bir vodvil yaratmaya'], 'Lagerlöf doğaüstü lanet söylencesini, köylülerin gizli suçluluk duygusu ve ahlaki hesaplaşmasıyla ustaca dengeler.'),
  ('Nikos Kazancakis\'in İsa\'nın çarmıhta son anlarını yaşarken sıradan bir aile hayatı kurma yanılsamasıyla sınanmasını ve bunu reddedip kurban olmayı seçmesini işlediği tartışmalı romanı hangisidir?', 'Günaha Son Çağrı', ['Yeniden Çarmıha Gerilen İsa', 'Allah\'ın Fukarası', 'Kardeş Kavgası'], '"Günaha Son Çağrı" (O Teleftaios Peirasmos), Kazancakis\'in ruh ile beden arasındaki amansız mücadeleyi İsa figürü üzerinden işlediği eserdir.'),
  ('Amin Maalouf\'un kendi dedesi Botros\'un mektup ve belgelerinden yola çıkarak 19. yüzyıl sonu Lübnan\'ından Küba\'ya uzanan gerçek aile tarihini kaleme aldığı anı-biyografi kitabı hangisidir?', 'Yolların Başlangıcı', ['Ölümcül Kimlikler', 'Tanios Kayası', 'Yüzüncü Ad'], '"Yolların Başlangıcı" (Origines), Maalouf\'un aydınlanmacı dedesi Botros ile Küba\'ya göç eden amcası Gebrayel\'in izini sürdüğü aile kroniğidir.'),
  ('Necib Mahfuz\'un "Binbir Gece Masalları"ndaki Şehrazat ve Şehriyar çerçevesini masallar bittikten sonraki döneme taşıyarak iktidar, yolsuzluk ve adalet sorunlarını büyülü gerçekçi bir dille işlediği romanı hangisidir?', 'Binbir Gecenin Geceleri', ['Midak Sokağı', 'Miramar', 'Saray Gezisi'], '1982 tarihli "Binbir Gecenin Geceleri" (Leyali Elfi Leyle), klasik Doğu masal mirasını modern politik ve ahlaki bir alegoriye dönüştürür.'),
  ('Cengiz Aytmatov\'un "Fujiyama\'da Buluşma" adlı tiyatro oyununda eski okul arkadaşlarının kutsal dağın zirvesinde buluşup aralarından cephede kaybolan şair Sabur\'un akıbetini konuşmaları hangi temayı deşer?', 'Stalin dönemi ihbarcılığında suskun kalan veya ihanet eden bireylerin yıllar geçse de kaçamadıkları vicdan muhasebesini', ['Japonya ile Kırgızistan arasında imzalanan dağcılık ve doğa sporları işbirliği anlaşmasının önemini', 'İkinci Dünya Savaşı sonrasında Asya ülkelerindeki volkanik dağların jeolojik olarak yeniden aktifleşmesini', 'Üniversite mezunlarının emeklilik döneminde kırsal turizm işletmeciliğine yönelmesinin ekonomik avantajlarını'], 'Muhammedcan ile birlikte yazılan oyunda Fujiyama (vicdan dağı), Sabur\'u ihbar eden kişinin ve buna göz yuman dostların ahlaki sınav yeridir.'),
  ('Cengiz Aytmatov\'un Kazak şair ve düşünür Muhtar Şahanov ile yaptığı uzun nehir söyleşilerden oluşan, tarih, kültür ve ahlak konularını tartıştıkları ortak kitabın adı nedir?', 'Şafak Sancısı', ['Yüz Yüze', 'Deve Gözü', 'Toprak Ana'], 'Aytmatov ve Şahanov\'un diyaloglarından oluşan eser, Türkçeye "Uçurumun Kenarındaki Avcının Çığlığı / Şafak Sancısı" adlarıyla çevrilmiştir.'),
  ('Bahtiyar Vahabzade\'nin 8. yüzyılda Arap hilafet ordularına karşı yirmi yılı aşkın süre Azerbaycan dağlarında direnen Hürremi lideri Babek\'in özgürlük mücadelesini işlediği tarihi piyesi hangisidir?', 'Dar Ağacı', ['İkinci Ses', 'Yağıştan Sonra', 'Kökler ve Budaklar'], '"Dar Ağacı" (Feryad / Babek temalı eserleriyle birlikte), işgale boyun eğmeyen tarihi direniş ruhunu sahneye taşır.'),
  ('Cengiz Aytmatov\'un ilk dönem öykülerinden "Deve Gözü"nde bozkırda bakir toprakları sürmeye giden idealist ve sanat ruhlu genç Kemal\'e acımasızca zorbalık eden kaba traktör şoförü kimdir?', 'Anarbay', ['Orozkul', 'Sabitcan', 'Bazarbay'], '"Deve Gözü"nde doğaya bir deve yavrusunun gözü kadar duyarlı bakan genç Kemal ile kaba güç temsilcisi Anarbay çatışır.'),
  ('Cengiz Aytmatov, Bahtiyar Vahabzade ve Muhammed Hüseyin Şehriyar\'ın 20. yüzyıl Türk dünyası edebiyatındaki tarihsel rollerini birleştiren temel özellik nedir?', 'Siyasi sınırlar ve kültürel asimilasyon baskıları altında yaşayan Türk halklarının ana dili, tarihsel bellek ve öz kimlik bilincini evrensel sanat düzeyinde korumaları', ['Geleneksel Türk edebiyatının tüm biçim ve temalarını reddederek yalnızca Batı avangart tiyatrosunu taklit etmeleri', 'Eserlerini kendi ana dilleri yerine yalnızca küresel diplomasi dillerinde yazarak yerel kültürden uzaklaşmaları', 'Tarihsel ve toplumsal sorunlara tamamen sırt çevirerek fildişi kulede bireysel soyut şiirler üretmeleri'], 'Kırgızistan\'da Aytmatov, Kuzey Azerbaycan\'da Vahabzade ve Güney Azerbaycan\'da Şehriyar; bellek, ana dili ve kimlik mücadelesinin üç büyük anıtıdır.'),
];
